import * as THREE from 'three';
const std=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.55,...extra});
export function setupAvatar(wrapper,height){const raw=wrapper.children[0];wrapper.remove(raw);const visual=new THREE.Group();visual.name='avatarVisual';visual.rotation.y=Math.PI;visual.position.y=-height/2;visual.add(raw);const motion=new THREE.Group();motion.name='avatarMotion';motion.position.y=height/2;motion.add(visual);wrapper.add(motion);wrapper.userData.motion=motion;wrapper.userData.height=height;return motion}
export function addSwimGear(wrapper,accent=0x62dbea){const h=wrapper.userData.height,motion=wrapper.userData.motion,gear=new THREE.Group();gear.name='swimGear';const finMat=std(accent,{transparent:true,opacity:.8});for(const side of [-1,1]){const pivot=new THREE.Group();pivot.position.set(side*h*.1,-h*.45,h*.03);const fin=new THREE.Mesh(new THREE.BoxGeometry(h*.12,h*.035,h*.28),finMat);fin.position.z=h*.13;fin.rotation.x=.08;pivot.add(fin);gear.add(pivot)}motion.add(gear);motion.userData.fins=gear.children;return gear}
export function addSpaceSuit(wrapper,{accent=0xe17da9}={}){const h=wrapper.userData.height,motion=wrapper.userData.motion,suit=new THREE.Group();suit.name='smallSpaceSuit';const white=std(0xf2eee5),dark=std(0x28334e,{metalness:.25}),color=std(accent,{emissive:accent,emissiveIntensity:.16});
 const helmet=new THREE.Mesh(new THREE.SphereGeometry(h*.205,20,14),new THREE.MeshPhysicalMaterial({color:0xcdeaff,transparent:true,opacity:.25,roughness:.05,metalness:.05,side:THREE.DoubleSide,depthWrite:false}));helmet.position.set(0,h*.32,-h*.015);helmet.scale.z=.92;suit.add(helmet);
 const collar=new THREE.Mesh(new THREE.TorusGeometry(h*.16,h*.035,8,24),white);collar.position.y=h*.18;collar.rotation.x=Math.PI/2;suit.add(collar);
 const chest=new THREE.Mesh(new THREE.BoxGeometry(h*.28,h*.22,h*.065),white);chest.position.set(0,h*.01,-h*.17);suit.add(chest);const panel=new THREE.Mesh(new THREE.BoxGeometry(h*.17,h*.08,h*.025),dark);panel.position.set(0,h*.02,-h*.21);suit.add(panel);for(const x of [-.045,0,.045]){const lamp=new THREE.Mesh(new THREE.SphereGeometry(h*.012,6,4),color);lamp.position.set(h*x,h*.025,-h*.23);suit.add(lamp)}
 const pack=new THREE.Mesh(new THREE.BoxGeometry(h*.27,h*.3,h*.14),white);pack.position.set(0,0,h*.17);suit.add(pack);for(const side of [-1,1]){const shoulder=new THREE.Mesh(new THREE.SphereGeometry(h*.075,10,7),white);shoulder.position.set(side*h*.18,h*.1,0);shoulder.scale.set(1,.75,1);suit.add(shoulder);const boot=new THREE.Mesh(new THREE.BoxGeometry(h*.12,h*.1,h*.17),dark);boot.position.set(side*h*.085,-h*.44,-h*.035);suit.add(boot);const jet=new THREE.Mesh(new THREE.ConeGeometry(h*.035,h*.13,8),color.clone());jet.position.set(side*h*.07,-h*.08,h*.27);jet.rotation.x=-Math.PI/2;suit.add(jet);(suit.userData.jets??=[]).push(jet)}
 const belt=new THREE.Mesh(new THREE.TorusGeometry(h*.15,h*.026,7,20),color);belt.position.y=-h*.12;belt.rotation.x=Math.PI/2;suit.add(belt);motion.add(suit);motion.userData.suit=suit;return suit}
export function animateAvatar(wrapper,{time,moving,space,phase=0}){const motion=wrapper.userData.motion;if(!motion)return;const h=wrapper.userData.height,wave=Math.sin(time*(moving?4.5:1.7)+phase);motion.position.y=h/2+Math.sin(time*2+phase)*h*(space?.018:.025);const targetPitch=space?(moving?-.18:-.04):(moving?-1.08:-.28);motion.rotation.x=THREE.MathUtils.lerp(motion.rotation.x,targetPitch,.08);motion.rotation.z=wave*(space?.075:.055);if(!space)motion.rotation.y=Math.sin(time*2.2+phase)*.035;
 const fins=motion.userData.fins;if(fins)fins.forEach((f,i)=>{f.rotation.x=(moving?wave*(i?-.45:.45):wave*.08)});const suit=motion.userData.suit;if(suit){suit.rotation.y=Math.sin(time*1.4+phase)*.035;suit.userData.jets?.forEach((j,i)=>{j.scale.y=moving?.75+Math.abs(Math.sin(time*7+i))*.8:.18;j.material.emissiveIntensity=moving?1.2:.2})}}
